class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = open(file_name, mode: "r") ?? panic("Cannot open file")
        let lines = file.readAllLines()
        file.close()

        if (lines.size == 0) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }

        let title = parse_line(lines[0])
        let data = ArrayList<ArrayList<String>>()

        for (i in 1..lines.size) {
            data.add(parse_line(lines[i]))
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = open(file_name, mode: "w") ?? return 0
        for (row in data) {
            let line = join_row(row)
            file.writeLine(line)
        }
        file.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        if (data.size == 0 || title.size <= N) {
            return 0
        }

        let new_data = ArrayList<ArrayList<String>>()
        new_data.add(title)

        for (row in data) {
            if (row.size > N) {
                let processed = row[N].toUppercase()
                new_data.add(ArrayList<String>([processed]))
            } else {
                new_data.add(ArrayList<String>([""]))
            }
        }

        let new_file_name = save_file_name + "_process"
        return write_csv(new_data, new_file_name)
    }

    private func parse_line(line: String): ArrayList<String> {
        let result = ArrayList<String>()
        let runes = line.toRuneArray()
        var i = 0
        var field_start = 0
        var in_quotes = false

        while (i < runes.size) {
            let r = runes[i]
            if (r == r'"') {
                in_quotes = !in_quotes
            } else if (r == r',' && !in_quotes) {
                let field = String(runes[field_start..i])
                result.add(unquote(field))
                field_start = i + 1
            }
            i = i + 1
        }

        let last_field = String(runes[field_start..runes.size])
        result.add(unquote(last_field))

        return result
    }

    private func unquote(field: String): String {
        let trimmed = field.trim()
        if (trimmed.size >= 2 && trimmed[0] == r'"' && trimmed[trimmed.size - 1] == r'"') {
            return trimmed[1..trimmed.size - 1]
        }
        return trimmed
    }

    private func join_row(row: ArrayList<String>): String {
        let parts = ArrayList<String>()
        for (field in row) {
            parts.add(quote_field(field))
        }
        return parts.join(",")
    }

    private func quote_field(field: String): String {
        if (field.contains(",") || field.contains("\"") || field.contains("\n")) {
            let escaped = field.replace("\"", "\"\"")
            return "\"" + escaped + "\""
        }
        return field
    }
}

import std.collection.HashMap
import std.collection.ArrayList
