class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum: Float64 = 0.0
        for (i in 0..data.size) {
            sum += data[i]
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        if (data.size == 0) {
            return 0.0 // Should ideally throw an exception or handle empty case
        }
        var min_val: Float64 = data[0]
        for (i in 1..data.size) {
            if (data[i] < min_val) {
                min_val = data[i]
            }
        }
        return min_val
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        if (data.size == 0) {
            return 0.0 // Should ideally throw an exception or handle empty case
        }
        var max_val: Float64 = data[0]
        for (i in 1..data.size) {
            if (data[i] > max_val) {
                max_val = data[i]
            }
        }
        return max_val
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        let n = data.size
        if (n <= 1) {
            return 0.0
        }
        let mean = get_sum() / Float64(n)
        var sum_sq_diff: Float64 = 0.0
        for (i in 0..n) {
            let diff = data[i] - mean
            sum_sq_diff += diff * diff
        }
        let variance = sum_sq_diff / Float64(n)
        return round(variance * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        let variance = get_variance()
        let std_dev = sqrt(variance)
        return round(std_dev * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        // For correlation, we correlate the data with itself, so it should be 1.0
        let n = data.size
        if (n <= 1) {
            return 0.0
        }

        let mean = get_sum() / Float64(n)
        var sum_sq_x: Float64 = 0.0
        var sum_sq_y: Float64 = 0.0
        var sum_prod: Float64 = 0.0

        // Since we are correlating data with itself (auto-correlation), x and y are the same
        for (i in 0..n) {
            let diff = data[i] - mean
            sum_sq_x += diff * diff
            sum_sq_y += diff * diff
            sum_prod += diff * diff
        }

        if (sum_sq_x == 0.0 || sum_sq_y == 0.0) {
            return 0.0
        }

        let correlation = sum_prod / sqrt(sum_sq_x * sum_sq_y)
        return round(correlation * 100.0) / 100.0
    }
}

