class JobMarketplace {

    /*
    This is a class that provides functionalities to publish positions, remove positions, submit resumes, withdraw resumes, search for positions, and obtain candidate information.
    */

    let jobListings: ArrayList<JobListing>
    let resumes: ArrayList<Resume>

    public init() {
        this.jobListings = ArrayList<JobListing>()
        this.resumes = ArrayList<Resume>()
    }

    public func post_job(job_title: String, company: String, requirements: ArrayList<String>): Unit {
        /*
        This function is used to publish positions,and add the position information to the job_listings list.
        :param job_title: The title of the position,String.
        :param company: The company of the position,String.
        :param requirements: The requirements of the position,ArrayList<String>.
        :return: Unit
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.post_job("Software Engineer", "ABC Company", ArrayList<String>(['requirement1', 'requirement2']))
        >>> jobMarketplace.job_listings
        [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['requirement1', 'requirement2']))]

        */
        let job = JobListing(job_title, company, requirements)
        this.jobListings.add(job)
    }

    public func remove_job(job: JobListing): Unit {
        /*
        This function is used to remove positions,and remove the position information from the job_listings list.
        :param job: The position information to be removed,JobListing.
        :return: Unit
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.job_listings = [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['requirement1', 'requirement2']))]
        >>> jobMarketplace.remove_job(jobMarketplace.job_listings[0])
        >>> jobMarketplace.job_listings
        []

        */
        this.jobListings.remove(job)
    }

    public func submit_resume(name: String, skills: ArrayList<String>, experience: String): Unit {
        /*
        This function is used to submit resumes,and add the resume information to the resumes list.
        :param name: The name of the resume,String.
        :param skills: The skills of the resume,ArrayList<String>.
        :param experience: The experience of the resume,String.
        :return: Unit
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.submit_resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")
        >>> jobMarketplace.resumes
        [Resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")]

        */
        let resume = Resume(name, skills, experience)
        this.resumes.add(resume)
    }

    public func withdraw_resume(resume: Resume): Unit {
        /*
        This function is used to withdraw resumes,and remove the resume information from the resumes list.
        :param resume: The resume information to be removed,Resume.
        :return: Unit
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.resumes = [Resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")]
        >>> jobMarketplace.withdraw_resume(jobMarketplace.resumes[0])
        >>> jobMarketplace.resumes
        []

        */
        this.resumes.remove(resume)
    }

    public func search_jobs(criteria: String): ArrayList<JobListing> {
        /*
        This function is used to search for positions,and return the position information that meets the requirements.
        :param criteria: The requirements of the position,String.
        :return: The position information that meets the requirements,ArrayList<JobListing>.
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.job_listings = [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['skill1', 'skill2']))]
        >>> jobMarketplace.search_jobs("skill1")
        [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['skill1', 'skill2']))]

        */
        let result = ArrayList<JobListing>()
        for (job in this.jobListings) {
            if (job.requirements.contains(criteria)) {
                result.add(job)
            }
        }
        return result
    }

    public func get_job_applicants(job: JobListing): ArrayList<Resume> {
        /*
        This function is used to obtain candidate information,and return the candidate information that meets the requirements by calling the matches_requirements function.
        :param job: The position information,JobListing.
        :return: The candidate information that meets the requirements,ArrayList<Resume>.
        >>> jobMarketplace = JobMarketplace()
        >>> jobMarketplace.resumes = [Resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")]
        >>> jobMarketplace.job_listings = [JobListing("Software Engineer", "ABC Company", ArrayList<String>(['skill1', 'skill2']))]
        >>> jobMarketplace.get_job_applicants(jobMarketplace.job_listings[0])
        [Resume("Tom", ArrayList<String>(['skill1', 'skill2']), "experience")]

        */
        let matched_resumes = ArrayList<Resume>()
        for (resume in this.resumes) {
            if (JobMarketplace.matches_requirements(resume, job.requirements)) {
                matched_resumes.add(resume)
            }
        }
        return matched_resumes
    }

    public static func matches_requirements(resume: Resume, requirements: ArrayList<String>): Bool {
        /*
        This function checks if a resume meets all the job requirements.
        It verifies whether the resume contains all the skills specified in the job requirements.

        :param resume: The resume to be evaluated, Resume object containing candidate's skills
        :param requirements: The list of required skills for the job, ArrayList<String>
        :return: Bool value indicating if the resume meets all requirements (true if all requirements are satisfied, false otherwise)
        */
        let skill_set = HashSet<String>(resume.skills)
        for (req in requirements) {
            if (!skill_set.contains(req)) {
                return false
            }
        }
        return true
    }
}

import std.collection.ArrayList
import std.math.abs

class KappaCalculator {

    /*
    This is a class as KappaCalculator, supporting to calculate Cohen's and Fleiss' kappa coefficient.
    */

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        /*
        Calculate the cohens kappa value of a k-dimensional matrix
        :param testData: The k-dimensional matrix that needs to calculate the cohens kappa value
        :param k: Int64, Matrix dimension
        :return:float, the cohens kappa value of the matrix
        >>> KappaCalculator.kappa(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 1, 1]), ArrayList<Int64>([1, 2, 1]), ArrayList<Int64>([1, 1, 2])]), 3)
        0.25
        */

        // Calculate total number of observations
        var total = 0.0
        for (i in 0..k) {
            for (j in 0..k) {
                total += Float64(testData[i][j])
            }
        }

        // Calculate observed agreement (Po)
        var po = 0.0
        for (i in 0..k) {
            po += Float64(testData[i][i])
        }
        po /= total

        // Calculate expected agreement (Pe)
        var pe = 0.0
        for (i in 0..k) {
            var rowSum = 0.0
            var colSum = 0.0
            for (j in 0..k) {
                rowSum += Float64(testData[i][j])
                colSum += Float64(testData[j][i])
            }
            pe += (rowSum * colSum) / (total * total)
        }

        // Calculate kappa
        let kappa = (po - pe) / (1.0 - pe)
        return kappa
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        /*
        Calculate the fliss kappa value of an N * k matrix
        :param testData: Input data matrix, N * k
        :param N: Int64, Number of samples
        :param k: Int64, Number of categories
        :param n: Int64, Number of raters
        :return: Float64, fleiss kappa value
        >>> KappaCalculator.fleiss_kappa(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0, 0, 0, 14]),
        >>>                              ArrayList<Int64>([0, 2, 6, 4, 2]),
        >>>                              ArrayList<Int64>([0, 0, 3, 5, 6]),
        >>>                              ArrayList<Int64>([0, 3, 9, 2, 0]),
        >>>                              ArrayList<Int64>([2, 2, 8, 1, 1]),
        >>>                              ArrayList<Int64>([7, 7, 0, 0, 0]),
        >>>                              ArrayList<Int64>([3, 2, 6, 3, 0]),
        >>>                              ArrayList<Int64>([2, 5, 3, 2, 2]),
        >>>                              ArrayList<Int64>([6, 5, 2, 1, 0]),
        >>>                              ArrayList<Int64>([0, 2, 2, 3, 7])], 10, 5, 14)
        0.20993070442195522
        */

        // Calculate Pj (proportion of all assignments to category j)
        var pj_array = ArrayList<Float64>([])
        for (j in 0..k) {
            var sum = 0.0
            for (i in 0..N) {
                sum += Float64(testData[i][j])
            }
            pj_array.add(sum / (Float64(N) * Float64(n)))
        }

        // Calculate Pi (extent to which raters agree for subject i)
        var pi_array = ArrayList<Float64>([])
        for (i in 0..N) {
            var sum = 0.0
            for (j in 0..k) {
                let x = Float64(testData[i][j])
                sum += x * x
            }
            pi_array.add((sum - Float64(n)) / (Float64(n) * (Float64(n) - 1.0)))
        }

        // Calculate P_bar (mean of Pi)
        var p_bar = 0.0
        for (i in 0..N) {
            p_bar += pi_array[i]
        }
        p_bar /= Float64(N)

        // Calculate Pe_bar
        var pe_bar = 0.0
        for (j in 0..k) {
            pe_bar += pj_array[j] * pj_array[j]
        }

        // Calculate Fleiss' Kappa
        let kappa = (p_bar - pe_bar) / (1.0 - pe_bar)
        return kappa
    }
}

import std.collection.ArrayList
import std.regex.Regex

class LongestWord {

    /*
    This is a class allows to add words to a list and find the longest word in a given sentence by comparing the words with the ones in the word list.
    */

    let word_list: ArrayList<String>

    public init() {
        /*
        Initialize a list of word.
        */
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        /*
        append the input word into this.word_list
        :param word: String, input word
        */
        this.word_list.add(word)
    }

    public func find_longest_word(sentence: String): String {
        /*
        Remove punctuation marks and split a sentence into a list of word. Find the longest splited word that is in the this.word_list.
        Words are strictly case sensitive.
        :param sentence: a sentence String
        :return String: longest splited word that is in the this.word_list. return '' if this.word_list is empty.
        >>> longestWord = LongestWord()
        >>> longestWord.add_word('A')
        >>> longestWord.add_word('aM')
        >>> longestWord.find_longest_word('I am a student.')
        'a'
        */
        if (this.word_list.size == 0) {
            return ""
        }

        // Remove punctuation using regex: replace all non-letter and non-space characters with empty string
        let cleaned = Regex("[^a-zA-Z ]").replaceAll(sentence, "")

        // Split by whitespace
        let words = cleaned.split(" ")

        var longest = ""
        for (word in words) {
            if (word != "" && this.word_list.contains(word) && word.size > longest.size) {
                longest = word
            }
        }
        return longest
    }
}

import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    /*
    MahjongConnect is a class representing a game board for Mahjong Connect with features like creating the board, checking valid moves, finding paths, removing icons, and checking if the game is over.
    */

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        /*
        initialize the board size and the icon list, create the game board
        :param BOARD_SIZE: list of two integer numbers, representing the number of rows and columns of the game board
        :param ICONS: list of String, representing the icons
        >>>mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.BOARD_SIZE = [4, 4]
        mc.ICONS = ['a', 'b', 'c']
        mc.board = mc.create_board()
        */
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = MahjongConnect.create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        create the game board with the given board size and icons
        :return: 2-dimensional list, the game board
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        >>> mc.create_board()
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        */
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let board = ArrayList<ArrayList<String>>()
        let rand = Random()

        for (i in 0..rows) {
            let row = ArrayList<String>()
            for (j in 0..cols) {
                let icon_index = rand.nextInt(ICONS.size.toUIntNative()).toInt64()
                row.add(ICONS[icon_index])
            }
            board.add(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        /*
        check if the move of two icons is valid (i.e. positions are within the game board range, the two positions are not the same, the two positions have the same icon, and there is a valid path between the two positions)
        :param pos1: position Tuple(x, y) of the first icon
        :param pos2: position Tuple(x, y) of the second icon
        :return:true or false ,representing whether the move of two icons is valid
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        >>> mc.is_valid_move((0, 0), (1, 0))
        true
        */
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]

        // Check bounds
        if (pos1[0] < 0 || pos1[0] >= rows || pos1[1] < 0 || pos1[1] >= cols ||
            pos2[0] < 0 || pos2[0] >= rows || pos2[1] < 0 || pos2[1] >= cols) {
            return false
        }

        // Check if positions are the same
        if (pos1 == pos2) {
            return false
        }

        // Check if icons are the same
        let icon1 = board[pos1[0]][pos1[1]]
        let icon2 = board[pos2[0]][pos2[1]]
        if (icon1 != icon2) {
            return false
        }

        // Check if there is a valid path
        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        /*
        check if there is a path between two icons
        :param pos1: position Tuple(x, y) of the first icon
        :param pos2: position Tuple(x, y) of the second icon
        :return: true or false ,representing whether there is a path between two icons
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        >>> mc.has_path((0, 0), (1, 0))
        true
        */
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let visited = ArrayList<(Int64, Int64)>()
        let queue = ArrayList<(Int64, Int64)>()

        queue.add(pos1)

        while (queue.size > 0) {
            let current = queue[0]
            queue.remove(at: 0)

            if (current == pos2) {
                return true
            }

            if (MahjongConnect.contains(visited, current)) {
                continue
            }
            visited.add(current)

            // Directions: up, down, left, right
            let directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
            for (dir in directions) {
                var x = current[0] + dir[0]
                var y = current[1] + dir[1]
                while (x >= 0 && x < rows && y >= 0 && y < cols && 
                       (board[x][y] == " " || (x == pos2[0] && y == pos2[1]))) {
                    let next = (x, y)
                    if (!MahjongConnect.contains(visited, next)) {
                        queue.add(next)
                    }
                    if (x == pos2[0] && y == pos2[1]) {
                        break
                    }
                    x += dir[0]
                    y += dir[1]
                }
            }
        }
        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        /*
        check if the position is in the visited list
        :param visited: list of position tuples, representing the visited positions
        :param pos: position tuple, representing the position to be checked
        :return: true or false, representing whether the position is in the visited list
        */
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        /*
        remove the connected icons on the game board
        :param pos1: position tuple(x, y) of the first icon to be removed
        :param pos2: position tuple(x, y) of the second icon to be removed
        :return: Unit
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        mc.board = [['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        >>> mc.remove_icons((0, 0), (1, 0))
        mc.board = [[' ', 'b', 'c', 'a'],
                    [' ', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a'],
                    ['a', 'b', 'c', 'a']]
        */
        board[pos1[0]][pos1[1]] = " "
        board[pos2[0]][pos2[1]] = " "
    }

    public func is_game_over(): Bool {
        /*
        Check if the game is over (i.e., if there are no more icons on the game board)
        :return: true or false ,representing whether the game is over
        >>> mc = MahjongConnect(ArrayList<Int64>([4, 4]), ArrayList<String>(['a', 'b', 'c']))
        >>> mc.board = [[' ', ' ', ' ', ' '],
        >>>         [' ', ' ', ' ', ' '],
        >>>         [' ', ' ', ' ', ' '],
        >>>         [' ', ' ', ' ', ' ']]
        >>> mc.is_game_over()
        true
        */
        for (row in board) {
            for (cell in row) {
                if (cell != " ") {
                    return false
                }
            }
        }
        return true
    }
}

import std.collection.*
import std.sort.*

class Manacher {
    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        let len = string.size
        if (center - diff < 0 || center + diff >= len) {
            return 0
        }
        if (string[center - diff] != string[center + diff]) {
            return 0
        }
        return 1 + palindromic_length(center, diff + 1, string)
    }

    public func palindromic_string(): String {
        // Preprocess the string to handle even-length palindromes
        let processed = this.preprocess(this.input_string)
        let n = processed.size
        var p = Array<Int64>([0] * n) // Array to store lengths of palindromes
        var center = 0
        var right = 0
        var max_len = 0
        var center_index = 0

        for (i in 0..n) {
            let mirror = 2 * center - i
            if (i < right) {
                p[i] = min(right - i, p[mirror])
            }

            // Try to expand palindrome centered at i
            let new_len = this.palindromic_length(i, p[i] + 1, processed)
            p[i] = p[i] + new_len

            // If palindrome centered at i extends past right, adjust center and right
            if (i + p[i] > right) {
                center = i
                right = i + p[i]
            }

            // Update max palindrome length and center index
            if (p[i] > max_len) {
                max_len = p[i]
                center_index = i
            }
        }

        // Extract the longest palindromic substring from original string
        let start = (center_index - max_len) // 2
        let length = max_len
        return this.input_string[start..start+length]
    }

    private func preprocess(s: String): String {
        let n = s.size
        if (n == 0) return "||"
        var result = "|"
        for (i in 0..n) {
            result = result + s[i] + "|"
        }
        return result
    }
}

main() {
    let manacher = Manacher("ababaxse")
    let result = manacher.palindromic_string()
    println(result) // Should print "ababa"
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator {

    /*
    The class calculates precision, recall, F1 score, and accuracy based on predicted and true labels.
    */

    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        /*
        Initialize the number of all four samples to 0
        */
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        /*
        Update the number of all four samples(true_positives, false_positives, false_negatives, true_negatives)
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: None, change the number of corresponding samples
        >>> mc = MetricsCalculator()
        >>> mc.update(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        (this.true_positives, this.false_positives, this.false_negatives, this.true_negatives) = (1, 1, 1, 1)
        */
        let size = predicted_labels.size

        for (i in 0..size) {
            let p = predicted_labels[i]
            let t = true_labels[i]

            if (p == 1 && t == 1) {
                this.true_positives += 1
            } else if (p == 1 && t == 0) {
                this.false_positives += 1
            } else if (p == 0 && t == 1) {
                this.false_negatives += 1
            } else if (p == 0 && t == 0) {
                this.true_negatives += 1
            }
        }
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate precision
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.precision(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        let denominator = this.true_positives + this.false_positives
        if (denominator == 0) {
            return 0.0
        }
        return (this.true_positives as Float64) / (denominator as Float64)
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.recall(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        let denominator = this.true_positives + this.false_negatives
        if (denominator == 0) {
            return 0.0
        }
        return (this.true_positives as Float64) / (denominator as Float64)
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate f1 score, which is the harmonic mean of precision and recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.f1_score(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        let p = this.precision(predicted_labels, true_labels)
        let r = this.recall(predicted_labels, true_labels)
        let denominator = p + r
        if (denominator == 0.0) {
            return 0.0
        }
        return 2.0 * (p * r) / denominator
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate accuracy
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.accuracy(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        this.update(predicted_labels, true_labels)
        let numerator = this.true_positives + this.true_negatives
        let denominator = numerator + this.false_positives + this.false_negatives
        if (denominator == 0) {
            return 0.0
        }
        return (numerator as Float64) / (denominator as Float64)
    }
}

import std.collection.*
import std.math.abs

class MetricsCalculator2 {

    /*
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP) based on input data, where MRR measures the ranking quality and MAP measures the average precision.
    */

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        let mrrList = ArrayList<Float64>()
        var totalMrr: Float64 = 0.0
        var count: Int64 = 0

        match (data) {
            case dataList: ArrayList<Any> => {
                for (item in dataList) {
                    let (actual, _) = item as (ArrayList<Int64>, Int64)
                    let reciprocalRank = calculateReciprocalRank(actual)
                    mrrList.add(reciprocalRank)
                    totalMrr += reciprocalRank
                    count += 1
                }
            }
            case singleData: (ArrayList<Int64>, Int64) => {
                let (actual, _) = singleData
                let reciprocalRank = calculateReciprocalRank(actual)
                mrrList.add(reciprocalRank)
                totalMrr += reciprocalRank
                count = 1
            }
            case _ => {
                throw "Invalid data format"
            }
        }

        let meanMrr = if (count > 0) { totalMrr / Float64(count) } else { 0.0 }
        return (meanMrr, mrrList)
    }

    private static func calculateReciprocalRank(actual: ArrayList<Int64>): Float64 {
        for (i in 0..actual.size) {
            if (actual[i] == 1) {
                return 1.0 / Float64(i + 1)
            }
        }
        return 0.0
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        let mapList = ArrayList<Float64>()
        var totalMap: Float64 = 0.0
        var count: Int64 = 0

        match (data) {
            case dataList: ArrayList<Any> => {
                for (item in dataList) {
                    let (actual, groundTruthNum) = item as (ArrayList<Int64>, Int64)
                    let ap = calculateAveragePrecision(actual, groundTruthNum)
                    mapList.add(ap)
                    totalMap += ap
                    count += 1
                }
            }
            case singleData: (ArrayList<Int64>, Int64) => {
                let (actual, groundTruthNum) = singleData
                let ap = calculateAveragePrecision(actual, groundTruthNum)
                mapList.add(ap)
                totalMap += ap
                count = 1
            }
            case _ => {
                throw "Invalid data format"
            }
        }

        let meanMap = if (count > 0) { totalMap / Float64(count) } else { 0.0 }
        return (meanMap, mapList)
    }

    private static func calculateAveragePrecision(actual: ArrayList<Int64>, groundTruthNum: Int64): Float64 {
        var ap: Float64 = 0.0
        var truePositives: Int64 = 0
        var totalRetrieved: Int64 = 0

        for (i in 0..actual.size) {
            totalRetrieved += 1
            if (actual[i] == 1) {
                truePositives += 1
                ap += Float64(truePositives) / Float64(totalRetrieved)
            }
        }

        if (groundTruthNum > 0) {
            ap /= Float64(groundTruthNum)
        } else {
            ap = 0.0
        }

        return ap
    }
}

import std.collection.ArrayList
import std.random.Random

class MinesweeperGame {
    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = MinesweeperGame.generate_mine_sweeper_map(n, k)
        this.player_map = MinesweeperGame.generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        // Initialize empty map with zeros
        let map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            let row = ArrayList<String>()
            for (j in 0..n) {
                row.add("0")
            }
            map.add(row)
        }

        // Place mines randomly
        var mines_placed = 0 as Int64
        let random = Random()
        while (mines_placed < k) {
            let x = random.nextInt(bound: n)
            let y = random.nextInt(bound: n)

            if (map[x][y] != "X") {
                map[x][y] = "X"
                mines_placed = mines_placed + 1

                // Update neighboring cells
                for (dx in -1..2) {
                    for (dy in -1..2) {
                        let nx = x + dx
                        let ny = y + dy
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && map[nx][ny] != "X") {
                            let current_value = map[nx][ny].parse(Int64) ?? 0
                            map[nx][ny] = (current_value + 1).toString()
                        }
                    }
                }
            }
        }

        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        let map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            let row = ArrayList<String>()
            for (j in 0..n) {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..this.n) {
            for (j in 0..this.n) {
                if (map[i][j] == "-" && this.minesweeper_map[i][j] != "X") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        // Check if position is out of bounds
        if (x < 0 || x >= this.n || y < 0 || y >= this.n) {
            return this.player_map
        }

        // If position already revealed
        if (this.player_map[x][y] != "-") {
            return this.player_map
        }

        // Hit a mine
        if (this.minesweeper_map[x][y] == "X") {
            this.player_map[x][y] = "X"
            return false  // Game over
        }

        // Reveal the position
        this.player_map[x][y] = this.minesweeper_map[x][y]
        this.score = this.score + 1

        // If it's an empty cell, reveal neighbors
        if (this.minesweeper_map[x][y] == "0") {
            for (dx in -1..2) {
                for (dy in -1..2) {
                    this.sweep(x + dx, y + dy)
                }
            }
        }

        // Check if player has won
        if (this.check_won(this.player_map)) {
            return true
        }

        return this.player_map
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime

class MovieBookingSystem {
    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        let movie = HashMap<String, Any>()
        movie.put("name", name)
        movie.put("price", price)
        movie.put("start_time", DateTime.parse(start_time, "yyyy/MM/dd HH:mm"))
        movie.put("end_time", DateTime.parse(end_time, "yyyy/MM/dd HH:mm"))

        let seats = ArrayList<ArrayList<Int64>>()
        for (i in 0..n) {
            let row = ArrayList<Int64>()
            for (j in 0..n) {
                row.add(0)
            }
            seats.add(row)
        }
        movie.put("seats", seats)

        movies.add(movie)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        for (movie in movies) {
            if (movie.get("name") == name) {
                let seats = movie.get("seats") as ArrayList<ArrayList<Int64>>
                var success = true

                for (seat in seats_to_book) {
                    let row = seat[0]
                    let col = seat[1]
                    if (seats[row][col] != 0) {
                        success = false
                        break
                    }
                }

                if (success) {
                    for (seat in seats_to_book) {
                        let row = seat[0]
                        let col = seat[1]
                        seats[row][col] = 1
                    }
                    return "Booking success."
                } else {
                    return "Booking failed."
                }
            }
        }
        return "Movie not found."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        let result = ArrayList<String>()
        let start = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let end = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")

        for (movie in movies) {
            let movie_start = movie.get("start_time") as DateTime
            let movie_end = movie.get("end_time") as DateTime

            if (start < movie_end && end > movie_start) {
                result.add(movie.get("name") as String)
            }
        }
        return result
    }
}

import std.random.Random
import std.collection.ArrayList
import std.sort.*

class MusicPlayer {

    /*
    This is a class as a music player that provides to play, stop, add songs, remove songs, set volume, shuffle, and switch to the next or previous song.
    */

    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        /*
        Initializes the music player with an empty playlist, no current song, and a default volume of 50.
        */
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        /*
        Adds a song to the playlist.
        :param song: The song to add to the playlist, String.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.add_song("song1")
        >>> musicPlayer.playlist
        ['song1']

        */
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        /*
        Removes a song from the playlist.
        :param song: The song to remove from the playlist, String.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.remove_song("song1")
        >>> musicPlayer.playlist
        ['song2']

        */
        if (this.playlist.contains(song)) {
            this.playlist.remove(song)
        }
    }

    public func play(): Option<String> {
        /*
        Plays the current song in the playlist.
        :return: The current song in the playlist, or "False" if there is no current song, or None if the playlist is empty, Option<String>.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.play()
        'song1'

        */
        return this.current_song
    }

    public func stop(): Bool {
        /*
        Stops the current song in the playlist.
        :return: true if the current song was stopped, false if there was no current song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.stop()
        true

        */
        if (this.current_song is None) {
            return false
        } else {
            this.current_song = None
            return true
        }
    }

    public func switch_song(): Bool {
        /*
        Switches to the next song in the playlist.
        :return: true if the next song was switched to, false if there was no next song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.switch_song()
        true

        */
        if (this.playlist.size == 0 || this.current_song is None) {
            return false
        }

        let current_index = this.playlist.indexOf((this.current_song as? String) ?? "")
        if (current_index == -1 || current_index + 1 >= this.playlist.size) {
            return false
        }

        this.current_song = Some(this.playlist[current_index + 1])
        return true
    }

    public func previous_song(): Bool {
        /*
        Switches to the previous song in the playlist.
        :return: true if the previous song was switched to, false if there was no previous song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song2"
        >>> musicPlayer.previous_song()
        true

        */
        if (this.playlist.size == 0 || this.current_song is None) {
            return false
        }

        let current_index = this.playlist.indexOf((this.current_song as? String) ?? "")
        if (current_index <= 0) {
            return false
        }

        this.current_song = Some(this.playlist[current_index - 1])
        return true
    }

    public func set_volume(volume: Int64): Bool {
        /*
        Sets the volume of the music player,ifthe volume is between 0 and 100 is valid.
        :param volume: The volume to set the music player to,Int64.
        :return: true if the volume was set, false if the volume was invalid.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.set_volume(50)
        true
        >>> musicPlayer.volume
        50

        */
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            return true
        } else {
            return false
        }
    }

    public func shuffle(): Bool {
        /*
        Shuffles the playlist.
        :return: true if the playlist was shuffled, false if the playlist was empty.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.shuffle()
        true

        */
        if (this.playlist.size == 0) {
            return false
        }

        sort(this.playlist, lessThan: { _, _ => Random.nextBool() })
        return true
    }
}

import std.collection.ArrayList
import std.collection.HashSet

class NLPDataProcessor {

    /*
    The class processes NLP data by removing stop words from a list of strings using a pre-defined stop word list.
    */

    public func construct_stop_word_list(): ArrayList<String> {
        /*
        Construct a stop word list including 'a', 'an', 'the'.
        :return: a list of stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> nlp_data_processor.construct_stop_word_list()
        ['a', 'an', 'the']
        */
        return ArrayList<String>(["a", "an", "the"])
    }

    public func remove_stop_words(string_list: ArrayList<String>, stop_word_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        Remove all the stop words from the list of strings.
        :param string_list: a list of strings
        :param stop_word_list: a list of stop words
        :return: a list of words without stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> nlp_data_processor.process(ArrayList<String>(['This is a test.']), ArrayList<String>(['a', 'an', 'the']))
        [['This', 'is', 'test.']]
        */
        let stop_word_set = HashSet<String>(stop_word_list)
        let result = ArrayList<ArrayList<String>>()

        for (s in string_list) {
            let words = s.split(" ")
            let filtered_words = ArrayList<String>()
            for (word in words) {
                if (!stop_word_set.contains(word)) {
                    filtered_words.add(word)
                }
            }
            result.add(filtered_words)
        }

        return result
    }

    public func process(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        Construct a stop word list including 'a', 'an', 'the', and remove all the stop words from the list of strings.
        :param string_list: a list of strings
        :return: a list of words without stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> NLPDataProcessor.process(ArrayList<String>(['This is a test.']))
        [['This', 'is', 'test.']]
        */
        let stop_word_list = this.construct_stop_word_list()
        return this.remove_stop_words(string_list, stop_word_list)
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    /*
    The class processes NLP data by extracting words from a list of strings, calculating the frequency of each word, and returning the top 5 most frequent words.
    */

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        keep only English letters and spaces in the string, then convert the string to lower case, and then split the string into a list of words.
        :param string_list: a list of strings
        :return: words_list: a list of words lists
        >>> NLPDataProcessor.process_data(ArrayList<String>(['This is a test.']))
        [['this', 'is', 'a', 'test']]
        */
        let result = ArrayList<ArrayList<String>>()
        let regex = Regex("[^a-zA-Z ]")

        for (s in string_list) {
            let cleaned = regex.replace(s, "")
            let lower_s = cleaned.toLower()
            let words = lower_s.split(' ').filter({w: String => w != ""})
            result.add(words)
        }

        return result
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        /*
        Calculate the word frequency of each word in the list of words list, and sort the word frequency dictionary by value in descending order.
        :param words_list: a list of words lists
        :return: top 5 word frequency dictionary, a dictionary of word frequency, key is word, value is frequency
        >>> NLPDataProcessor.calculate_word_frequency(ArrayList<ArrayList<String>>([ArrayList<String>(['this', 'is', 'a', 'test']), ArrayList<String>(['this', 'is', 'another', 'test'])]))
        {'this': 2, 'is': 2, 'test': 2, 'a': 1, 'another': 1}
        */
        let freq_map = HashMap<String, Int64>()

        for (words in words_list) {
            for (word in words) {
                if (freq_map.contains(word)) {
                    freq_map[word] = freq_map[word] + 1
                } else {
                    freq_map[word] = 1
                }
            }
        }

        return freq_map
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        /*
        keep only English letters and spaces in the string, then convert the string to lower case, and then split the string into a list of words. Calculate the word frequency of each word in the list of words list, and sort the word frequency dictionary by value in descending order.
        :param string_list: a list of strings
        :return: top 5 word frequency dictionary, a dictionary of word frequency, key is word, value is frequency
        >>> NLPDataProcessor.process(ArrayList<String>(['This is a test.', 'This is another test.']))
        {'this': 2, 'is': 2, 'test': 2, 'a': 1, 'another': 1}
        */
        let words_list = this.process_data(string_list)
        let freq_map = this.calculate_word_frequency(words_list)

        // Convert HashMap to list of (word, frequency) pairs for sorting
        let entries = ArrayList<(String, Int64)>()
        for (entry in freq_map.entries()) {
            entries.add((entry.key, entry.value))
        }

        // Sort by frequency descending, then by word ascending for tie-breaking
        sort(entries, lessThan: { a, b =>
            if (a[1] != b[1]) {
                a[1] > b[1]  // Descending frequency
            } else {
                a[0] < b[0]  // Ascending word order for ties
            }
        })

        // Take top 5
        let top_5_map = HashMap<String, Int64>()
        var count = 0
        for (entry in entries) {
            if (count >= 5) { break }
            top_5_map[entry[0]] = entry[1]
            count = count + 1
        }

        return top_5_map
    }
}

import std.convert.Formattable
import std.convert.Parsable
import std.convert.RadixConvertible

class NumberConverter {

    /*
    The class allows to convert  decimal to binary, octal and hexadecimal repectively and contrarily
    */

    public static func decimal_to_binary(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to binary format.
        :param decimal_num: Int64, decimal number
        :return: String, the binary representation of an integer.
        >>> NumberConverter.decimal_to_binary(42423)
        '1010010110110111'
        */
        return decimal_num.toString(radix: 2)
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        /*
        Convert a number from binary format to decimal format.
        :param binary_num: String, binary number
        :return: Int64, the decimal representation of binary number str.
        >>> NumberConverter.binary_to_decimal('1010010110110111')
        42423
        */
        return Int64.parse(binary_num, radix: 2).getOrThrow()
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to octal format.
        :param decimal_num: Int64, decimal number
        :return: String, the octal representation of an integer.
        >>> NumberConverter.decimal_to_octal(42423)
        '122667'
        */
        return decimal_num.toString(radix: 8)
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        /*
        Convert a number from octal format to decimal format.
        :param octal_num: String, octal number
        :return: Int64, the decimal representation of octal number str.
        >>> NumberConverter.octal_to_decimal('122667')
        42423
        */
        return Int64.parse(octal_num, radix: 8).getOrThrow()
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        /*
        Convert a number from decimal format to hex format.
        :param decimal_num: Int64, decimal number
        :return hex_num: String, the hex representation of an integer.
        >>> NumberConverter.decimal_to_hex(42423)
        'a5b7'
        */
        return decimal_num.toString(radix: 16)
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        /*
        Convert a number from hex format to decimal format.
        :param hex_num: String, hex num
        :return: Int64, the decimal representation of hex number str.
        >>> NumberConverter.hex_to_decimal('a5b7')
        42423
        */
        return Int64.parse(hex_num, radix: 16).getOrThrow()
    }
}

