        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        /*
        Converts a number into words format
        :param x: Option<String>, the number to be converted into words format
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        if (x is None<String>) {
            return ""
        }
        let value = x.getOrThrow()
        return this.format_string(value)
    }

    public func format_string(x: String): String {
        /*
        Converts a string representation of a number into words format
        :param x: String, the string representation of a number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        if (x == "") {
            return ""
        }
        let parts = x.split('.')
        let integer_part = parts[0]
        let decimal_part = if (parts.size > 1) { parts[1] } else { "" }

        let integer_words = this.convert_integer(integer_part)
        let decimal_words = if (decimal_part != "") { 
            let decimal_str = this.convert_decimal(decimal_part)
            " AND CENTS " + decimal_str + " ONLY"
        } else {
            " ONLY"
        }

        return integer_words + decimal_words
    }

    private func convert_integer(num_str: String): String {
        /*
        Converts the integer part of a number into words.
        */
        if (num_str == "" || num_str == "0") {
            return "ZERO"
        }

        let clean_num = this.strip_leading_zeros(num_str)
        let length = clean_num.size
        let groups = (length + 2) / 3 // Number of three-digit groups
        let padded_length = groups * 3
        let padded_num = clean_num.padStart(padded_length, '0')

        var result_parts = ArrayList<String>()

        for (i in 0..groups) {
            let start_index = i * 3
            let segment = padded_num.substring(start_index, start_index + 3)
            if (segment != "000") {
                let segment_text = this.trans_three(segment)
                let suffix = this.parse_more(groups - i - 1)
                let segment_with_suffix = if (suffix != "") {
                    segment_text + " " + suffix
                } else {
                    segment_text
                }
                result_parts.add(segment_with_suffix)
            }
        }

        return result_parts.join(" ")
    }

    private func convert_decimal(num_str: String): String {
        /*
        Converts the decimal part of a number into words.
        */
        if (num_str == "") {
            return ""
        }
        let clean_num = this.strip_trailing_zeros(num_str)
        if (clean_num == "") {
            return ""
        }
        return this.trans_two(clean_num.padEnd(2, '0').substring(0, 2))
    }

    private func strip_leading_zeros(s: String): String {
        /*
        Removes leading zeros from a string.
        */
        var i = 0
        while (i < s.size && s[i] == '0') {
            i += 1
        }
        return if (i < s.size) { s.substring(i) } else { "0" }
    }

    private func strip_trailing_zeros(s: String): String {
        /*
        Removes trailing zeros from a string.
        */
        var i = s.size - 1
        while (i >= 0 && s[i] == '0') {
            i -= 1
        }
        return if (i >= 0) { s.substring(0, i + 1) } else { "" }
    }

    public func trans_two(s: String): String {
        /*
        Converts a two-digit number into words format
        :param s: String, the two-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        */
        let num = s.parse<Int64>().getOrThrow()
        if (num < 10) {
            return this.NUMBER[num]
        } else if (num < 20) {
            return this.NUMBER_TEEN[num - 10]
        } else {
            let tens = num / 10
            let units = num % 10
            let tens_word = this.NUMBER_TEN[tens - 1]
            if (units == 0) {
                return tens_word
            } else {
                return tens_word + " " + this.NUMBER[units]
            }
        }
    }

    public func trans_three(s: String): String {
        /*
        Converts a three-digit number into words format
        :param s: String, the three-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        */
        let num = s.parse<Int64>().getOrThrow()
        let hundreds = num / 100
        let remainder = num % 100

        if (hundreds == 0) {
            return this.trans_two(remainder.toString())
        }

        let hundreds_word = this.NUMBER[hundreds] + " HUNDRED"
        if (remainder == 0) {
            return hundreds_word
        } else {
            return hundreds_word + " AND " + this.trans_two(remainder.toString())
        }
    }

    public func parse_more(i: Int64): String {
        /*
        Parses the thousand/million/billion suffix based on the index
        :param i: Int64, the index representing the magnitude (thousand, million, billion)
        :return: String, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        */
        if (i < this.NUMBER_MORE.size) {
            return this.NUMBER_MORE[i]
        }
        return ""
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    /*
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    */

    public init() {}

    public func replace(string: String): String {
        /*
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: String, the input string containing numeric character references.
        :return: String, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        */
        var result = ArrayList<Rune>()
        let runes = string.toRuneArray()
        var i = 0

        while (i < runes.size) {
            if (runes[i] == r'&' && i + 1 < runes.size && runes[i + 1] == r'#') {
                // Start of a numeric entity
                var j = i + 2
                var is_hex = false

                if (j < runes.size && (runes[j] == r'x' || runes[j] == r'X')) {
                    is_hex = true
                    j += 1
                }

                let start = j
                while (j < runes.size && runes[j] != r';') {
                    j += 1
                }

                if (j < runes.size && runes[j] == r';') {
                    let number_str = String(runes[start..<j])
                    var code_point: Int64 = 0
                    if (is_hex) {
                        code_point = Int64(number_str, radix: 16) ?? 0
                    } else {
                        code_point = Int64(number_str, radix: 10) ?? 0
                    }

                    if (code_point > 0) {
                        result.add(Rune(code_point))
                    } else {
                        // If conversion fails, keep original
                        for (k in i..(j+1)) {
                            result.add(runes[k])
                        }
                    }
                    i = j + 1
                } else {
                    // No semicolon found, treat as normal text
                    result.add(runes[i])
                    i += 1
                }
            } else {
                result.add(runes[i])
                i += 1
            }
        }

        return String(result)
    }

    public static func is_hex_char(char: Rune): Bool {
        /*
        Determines whether a given character is a hexadecimal digit.
        :param char: Rune, the character to check.
        :return: Bool, true if the character is a hexadecimal digit, false otherwise.
        >>> NumericEntityUnescaper.is_hex_char(r'a')
        true

        */
        let c = char.toChar() // Assuming Rune has a method to convert to char or similar logic
        return ('0' <= c && c <= '9') || 
               ('a' <= c && c <= 'f') || 
               ('A' <= c && c <= 'F')
    }
}

