class VendingMachine {

    /*
    This is a class to simulate a vending machine, including adding products, inserting coins, purchasing products, viewing balance, replenishing product inventory, and displaying product information.
    */

    var inventory: HashMap<String, Product>
    var balance: Float64

    public init() {
        /*
        Initializes the vending machine's inventory and balance.
        */
        this.inventory = HashMap<String, Product>()
        this.balance = 0.0
    }

    public func add_item(item_name: String, price: Float64, quantity: Int64): Unit {
        /*
        Adds a product to the vending machine's inventory.
        :param item_name: The name of the product to be added, String.
        :param price: The price of the product to be added, Float64.
        :param quantity: The quantity of the product to be added, Int64.
        :return: Unit
        >>> vendingMachine = VendingMachine()
        >>> vendingMachine.add_item('Coke', 1.25, 10)
        >>> vendingMachine.inventory
        {'Coke': Product(1.25, 10)}

        */
        this.inventory.add(item_name, Product(price, quantity))
    }

    public func insert_coin(amount: Float64): Float64 {
        /*
        Inserts coins into the vending machine.
        :param amount: The amount of coins to be inserted, Float64.
        :return: The balance of the vending machine after the coins are inserted, Float64.
        >>> vendingMachine = VendingMachine()
        >>> vendingMachine.insert_coin(1.25)
        1.25

        */
        this.balance += amount
        return this.balance
    }

    public func purchase_item(item_name: String): Option<Float64> {
        /*
        Purchases a product from the vending machine and returns the balance after the purchase and display purchase unsuccessful if the product is out of stock.
        :param item_name: The name of the product to be purchased, String.
        :return: If successful, returns the balance of the vending machine after the product is purchased, Float64,otherwise,returns None.
        >>> vendingMachine = VendingMachine()
        >>> vendingMachine.inventory = HashMap<String, Product>([('Coke', Product(1.25, 10))])
        >>> vendingMachine.balance = 1.25
        >>> vendingMachine.purchase_item('Coke')
        0.0
        >>> vendingMachine.purchase_item('Pizza')
        None

        */
        let productOpt = this.inventory.get(item_name)
        if (productOpt is Some<Product>) {
            let product = productOpt.getOrThrow()
            if (product.quantity > 0 && this.balance >= product.price) {
                product.quantity -= 1
                this.balance -= product.price
                return Some<Float64>(this.balance)
            }
        }
        return None<Float64>()
    }

    public func restock_item(item_name: String, quantity: Int64): Bool {
        /*
        Replenishes the inventory of a product already in the vending machine.
        :param item_name: The name of the product to be replenished, String.
        :param quantity: The quantity of the product to be replenished, Int64.
        :return: If the product is already in the vending machine, returns true, otherwise, returns false.
        >>> vendingMachine = VendingMachine()
        >>> vendingMachine.inventory = HashMap<String, Product>([('Coke', Product(1.25, 10))])
        >>> vendingMachine.restock_item('Coke', 10)
        true
        >>> vendingMachine.restock_item('Pizza', 10)
        false

        */
        let productOpt = this.inventory.get(item_name)
        if (productOpt is Some<Product>) {
            productOpt.getOrThrow().quantity += quantity
            return true
        }
        return false
    }

    public func display_items(): Option<String> {
        /*
        Displays the products in the vending machine.
        :return: If the vending machine is empty, returns None, otherwise, returns a list of the products in the vending machine, String.
        >>> vendingMachine = VendingMachine()
        >>> vendingMachine.display_items()
        None
        >>> vendingMachine.inventory = HashMap<String, Product>([('Coke', Product(1.25, 10))])
        >>> vendingMachine.display_items()
        'Coke - $1.250000 [10]'

        */
        if (this.inventory.size == 0) {
            return None<String>()
        }

        var result = ""
        var first = true
        for ((name, product) in this.inventory) {
            if (!first) {
                result += "\n"
            }
            result += "${name} - $${product.price} [${product.quantity}]"
            first = false
        }
        return Some<String>(result)
    }
}

import std.collection.*

class Product <: Equatable<Product> {

    let name: String
    var quantity: Int64

    public init(name: String, quantity: Int64) {
        this.name = name
        this.quantity = quantity
    }

    public override operator func != (that: Product): Bool {
        return this.name != that.name || this.quantity != that.quantity
    }

    public override operator func == (that: Product): Bool {
        return this.name == that.name && this.quantity == that.quantity
    }
}

class Order <: Equatable<Order> {

    let product_id: Int64
    let quantity: Int64
    var status: String

    public init(product_id: Int64, quantity: Int64, status: String) {
        this.product_id = product_id
        this.quantity = quantity
        this.status = status
    }

    public override operator func != (that: Order): Bool {
        return this.product_id != that.product_id || this.quantity != that.quantity || this.status != that.status
    }

    public override operator func == (that: Order): Bool {
        return this.product_id == that.product_id && this.quantity == that.quantity && this.status == that.status
    }
}

class Warehouse {

    let inventory: HashMap<Int64, Product>
    let orders: HashMap<Int64, Order>

    public init() {
        this.inventory = HashMap<Int64, Product>()
        this.orders = HashMap<Int64, Order>()
    }

    public func add_product(product_id: Int64, name: String, quantity: Int64): Unit {
        if (this.inventory.contains(product_id)) {
            let product = this.inventory[product_id] ?? panic("Product not found")
            product.quantity += quantity
        } else {
            let product = Product(name, quantity)
            this.inventory.add(product_id, product)
        }
    }

    public func update_product_quantity(product_id: Int64, quantity: Int64): Unit {
        if (this.inventory.contains(product_id)) {
            let product = this.inventory[product_id] ?? panic("Product not found")
            product.quantity += quantity
        }
    }

    public func get_product_quantity(product_id: Int64): Option<Int64> {
        if (this.inventory.contains(product_id)) {
            let product = this.inventory[product_id] ?? panic("Product not found")
            return Some<Int64>(product.quantity)
        } else {
            return None<Int64>
        }
    }

    public func create_order(order_id: Int64, product_id: Int64, quantity: Int64): Bool {
        if (!this.inventory.contains(product_id)) {
            return false
        }

        let product = this.inventory[product_id] ?? panic("Product not found")
        if (product.quantity < quantity) {
            return false
        }

        product.quantity -= quantity
        let order = Order(product_id, quantity, "Shipped")
        this.orders.add(order_id, order)
        return true
    }

    public func change_order_status(order_id: Int64, status: String): Bool {
        if (!this.orders.contains(order_id)) {
            return false
        }

        let order = this.orders[order_id] ?? panic("Order not found")
        order.status = status
        return true
    }

    public func track_order(order_id: Int64): Option<String> {
        if (!this.orders.contains(order_id)) {
            return None<String>
        }

        let order = this.orders[order_id] ?? panic("Order not found")
        return Some<String>(order.status)
    }
}

import std.collection.HashMap
import std.math.abs

class Weather {

    let weather: String
    let temperature: Float64
    let temperature_units: String

    public init(weather: String, temperature: Float64, temperature_units: String) {
        this.weather = weather
        this.temperature = temperature
        this.temperature_units = temperature_units
    }
}

class WeatherSystem {

    /*
    This is a class representing a weather system that provides functionality to query weather information for a specific city and convert temperature units between Celsius and Fahrenheit.
    */

    var temperature: Float64
    var weather: String
    var city: String
    var weather_list: HashMap<String, Weather>

    public init(city: String) {
        /*
        Initialize the weather system with a city name.
        */
        this.temperature = Float64.NaN
        this.weather = ""
        this.city = city
        this.weather_list = HashMap<String, Weather>()
    }

    public func query(weather_list: HashMap<String, Weather>, tmp_units!: String = "celsius"): Option<(Float64, String)> {
        /*
        Query the weather system for the weather and temperature of the city,and convert the temperature units based on the input parameter.
        :param weather_list: a dictionary of weather information for different cities,HashMap<String, Weather>.
        :param tmp_units: the temperature units to convert to, String.
        :return: the temperature and weather of the city, Option<Float64, String>.
        >>> weatherSystem = WeatherSystem('New York')
        >>> weather_list = HashMap<String, Weather>()
        >>> weather_list['New York'] = Weather('sunny', 27.0, 'celsius')
        >>> weather_list['Beijing'] = Weather('cloudy', 23.0, 'celsius')
        >>> weatherSystem.query(weather_list)
        (27.0, 'sunny')

        */
        if (weather_list.contains(this.city)) {
            let weather_info = weather_list[this.city]
            let temp = weather_info.temperature
            let units = weather_info.temperature_units
            let weather_str = weather_info.weather

            // Convert temperature if needed
            var converted_temp = temp
            if (tmp_units == "fahrenheit" && units == "celsius") {
                converted_temp = temp * 9.0 / 5.0 + 32.0
            } else if (tmp_units == "celsius" && units == "fahrenheit") {
                converted_temp = (temp - 32.0) * 5.0 / 9.0
            }

            return Some<(Float64, String)>((converted_temp, weather_str))
        }
        return None<(Float64, String)>
    }

    public func set_city(city: String): Unit {
        /*
        Set the city of the weather system.
        :param city: the city to set, String.
        :return: Unit
        >>> weatherSystem = WeatherSystem('New York')
        >>> weatherSystem.set_city('Beijing')
        >>> weatherSystem.city
        'Beijing'

        */
        this.city = city
    }

    public func celsius_to_fahrenheit(): Float64 {
        /*
        Convert the temperature from Celsius to Fahrenheit.
        :return: the temperature in Fahrenheit, Float64.
        >>> weatherSystem = WeatherSystem('New York')
        >>> weatherSystem.temperature = 27.0
        >>> weatherSystem.celsius_to_fahrenheit()
        80.6

        */
        return this.temperature * 9.0 / 5.0 + 32.0
    }

    public func fahrenheit_to_celsius(): Float64 {
        /*
        Convert the temperature from Fahrenheit to Celsius.
        :return: the temperature in Celsius, Float64.
        >>> weatherSystem = WeatherSystem('New York')
        >>> weatherSystem.temperature = 80.6
        >>> weatherSystem.fahrenheit_to_celsius()
        26.999999999999996

        */
        return (this.temperature - 32.0) * 5.0 / 9.0
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Words2Numbers {

    /*
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    */

    let numwords: HashMap<String, (Int64, Int64)>
    let units: ArrayList<String>
    let tens: ArrayList<String>
    let scales: ArrayList<String>
    let ordinal_words: HashMap<String, Int64>
    let ordinal_endings: ArrayList<(String, String)>

    public init() {
        /*
        Initialize the word lists and dictionaries required for conversion
        */
        this.numwords = HashMap<String, (Int64, Int64)>()
        this.units = ArrayList<String>(["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"])
        this.tens = ArrayList<String>(["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"])
        this.scales = ArrayList<String>(["hundred", "thousand", "million", "billion", "trillion"])

        this.numwords["and"] = (1, 0)
        for (idx in 0..this.units.size) {
            this.numwords[this.units[idx]] = (1, idx)
        }
        for (idx in 0..this.tens.size) {
            this.numwords[this.tens[idx]] = (1, idx * 10)
        }
        for (idx in 0..this.scales.size) {
            if (idx * 3 == 0) {
                this.numwords[this.scales[idx]] = (10 ** 2, 0)
            } else {
                this.numwords[this.scales[idx]] = (Int64(10.0 ** (idx * 3)), 0)
            }
        }

        this.ordinal_words = HashMap<String, Int64>([("first", 1), ("second", 2), ("third", 3), ("fifth", 5), ("eighth", 8), ("ninth", 9), ("twelfth", 12)])
        this.ordinal_endings = ArrayList<(String, String)>([("ieth", "y"), ("th", "")])
    }

    public func text2int(textnum: String): String {
        /*
        Convert the word string to the corresponding integer string
        :param textnum: String, the word string to be converted
        :return: String, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        */
        let tokens = textnum.split('-')
        var current: Int64 = 0
        var result: Int64 = 0

        for (token in tokens) {
            let word = token.toLowerCase()
            if (this.numwords.contains(word)) {
                let value = this.numwords[word]
                let scale = value[0]
                let increment = value[1]
                current = current * scale + increment
                if (scale > 100) {
                    result += current
                    current = 0
                }
            } else {
                return "Invalid input"
            }
        }
        return "${result + current}"
    }

    public func is_valid_input(textnum: String): Bool {
        /*
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: true if input is valid, false otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        false
        */
        let tokens = textnum.split('-')
        for (token in tokens) {
            let word = token.toLowerCase()
            if (!this.numwords.contains(word)) {
                return false
            }
        }
        return true
    }
}
